const fs = require('fs');
// Installation: clir completion >> ~/.bashrc (or ~/.zshrc)
function install(){ const rc = process.env.HOME + '/.bashrc'; fs.appendFileSync(rc, '\n. <(clir completion)\n'); }
module.exports = { install };

